-- bm Font: Advanced font editor for BareMetal (640x360)
-- Create, edit, and organize bitmap fonts in /bmf/ with .bmf extension.

local HEX_ORIG_8X16 = ""
local HEX_INTER_8X16 = ""
local HEX_6X12 = ""

-- Palette
local C = {
  bg = 0x0A0E14,
  panel = 0x141B24,
  panel_hi = 0x1E293B,
  border = 0x2D3748,
  border_hi = 0x4A5568,
  grid = 0x1F2937,
  grid_dot = 0x374151,
  pixel_on = 0x00E5FF,
  pixel_off = 0x111827,
  accent = 0xFF9100,
  text = 0xE2E8F0,
  dim = 0x64748B,
  btn = 0x1E293B,
  btn_hi = 0x334155,
  btn_text = 0xF1F5F9,
  cyan = 0x00E5FF,
  green = 0x10B981,
  yellow = 0xFBBF24,
  red = 0xEF4444,
  white = 0xFFFFFF,
  black = 0x000000,
}

local fonts = {}
local active_font_idx = 1
local cur_font = nil
local cur_char = 65 -- 'A'
local clipboard = nil

local notice = "bm Font pronto (/bmf)"
local notice_timer = 120

-- UI State
local preview_scale = 1 -- 1, 2, or 3
local dropdown_open = false
local dropdown_sel_idx = 1
local new_modal_open = false
local new_font_size = "8x16"
local new_font_base = "inter"

local function set_notice(msg)
  notice = msg
  notice_timer = 150
end

local function parse_hex_glyphs(hex_str, height)
  local gl = {}
  local total_chars = 256
  local hex_len = #hex_str
  local expected = total_chars * height * 2
  local ptr = 1
  for i = 0, total_chars - 1 do
    gl[i] = {}
    for y = 1, height do
      if ptr + 1 <= hex_len then
        local b_str = hex_str:sub(ptr, ptr + 1)
        gl[i][y] = tonumber(b_str, 16) or 0
        ptr = ptr + 2
      else
        gl[i][y] = 0
      end
    end
  end
  return gl
end

local function load_bmf_data(stem, raw)
  if #raw < 32 then return nil end
  if raw:sub(1, 6) ~= "BMFONT" then return nil end
  local w = raw:byte(9)
  local h = raw:byte(10)
  local count = raw:byte(11) + raw:byte(12) * 256
  local name = raw:sub(17, 32):gsub("%z.*", "")
  if name == "" then name = stem end
  local gl = {}
  local ptr = 33
  for i = 0, count - 1 do
    gl[i] = {}
    for y = 1, h do
      gl[i][y] = raw:byte(ptr) or 0
      ptr = ptr + 1
    end
  end
  return { name = name, stem = stem, cw = w, ch = h, glyphs = gl }
end

local function pack_bmf(font)
  local magic = "BMFONT\1\0"
  local dims = string.char(font.cw, font.ch)
  local count = string.char(256 % 256, math.floor(256 / 256))
  local res = "\0\0\0\0"
  local n = (font.name or font.stem):sub(1, 15)
  local name_padded = n .. string.rep("\0", 16 - #n)
  local header = magic .. dims .. count .. res .. name_padded
  local bytes = {}
  for i = 0, 255 do
    local g = font.glyphs[i] or {}
    for y = 1, font.ch do
      table.insert(bytes, string.char(g[y] or 0))
    end
  end
  return header .. table.concat(bytes)
end

local function init_fonts()
  fonts = {}
  local loaded_any = false
  if font_list then
    local list = font_list()
    if list and #list > 0 then
      for _, item in ipairs(list) do
        local raw = font_read(item.name)
        if raw then
          local f = load_bmf_data(item.name, raw)
          if f then
            table.insert(fonts, f)
            loaded_any = true
          end
        end
      end
    end
  end

  if not loaded_any then
    table.insert(fonts, { name = "Terminus", stem = "terminus", cw = 8, ch = 16, glyphs = parse_hex_glyphs(HEX_ORIG_8X16, 16) })
    table.insert(fonts, { name = "Inter", stem = "inter", cw = 8, ch = 16, glyphs = parse_hex_glyphs(HEX_INTER_8X16, 16) })
    table.insert(fonts, { name = "6x12", stem = "6x12", cw = 6, ch = 12, glyphs = parse_hex_glyphs(HEX_6X12, 12) })
    if font_write then
      for _, f in ipairs(fonts) do
        font_write(f.stem, pack_bmf(f))
      end
    end
  end

  active_font_idx = 1
  cur_font = fonts[1]
  cur_char = 65
end

local function select_font(idx)
  if idx >= 1 and idx <= #fonts then
    active_font_idx = idx
    cur_font = fonts[idx]
  end
end

local function get_glyph(c)
  if not cur_font.glyphs[c] then
    cur_font.glyphs[c] = {}
    for y = 1, cur_font.ch do
      cur_font.glyphs[c][y] = 0
    end
  end
  return cur_font.glyphs[c]
end

local function get_pixel(c, x, y)
  local g = get_glyph(c)
  local row = g[y] or 0
  local shift = cur_font.cw - x
  return (row & (1 << shift)) ~= 0
end

local function set_pixel(c, x, y, val)
  local g = get_glyph(c)
  local row = g[y] or 0
  local shift = cur_font.cw - x
  if val then
    row = row | (1 << shift)
  else
    row = row & ~(1 << shift)
  end
  g[y] = row
end

local function clear_glyph()
  local g = get_glyph(cur_char)
  for y = 1, cur_font.ch do
    g[y] = 0
  end
  set_notice("Glyph cleared")
end

local function invert_glyph()
  local g = get_glyph(cur_char)
  local mask = (1 << cur_font.cw) - 1
  for y = 1, cur_font.ch do
    g[y] = (g[y] ~ mask) & mask
  end
  set_notice("Glyph inverted")
end

local function flip_h()
  local g = get_glyph(cur_char)
  for y = 1, cur_font.ch do
    local r = g[y]
    local nr = 0
    for x = 1, cur_font.cw do
      if (r & (1 << (cur_font.cw - x))) ~= 0 then
        nr = nr | (1 << (x - 1))
      end
    end
    g[y] = nr
  end
  set_notice("Flipped horizontally")
end

local function flip_v()
  local g = get_glyph(cur_char)
  local top, bot = 1, cur_font.ch
  while top < bot do
    g[top], g[bot] = g[bot], g[top]
    top = top + 1
    bot = bot - 1
  end
  set_notice("Flipped vertically")
end

local function shift_glyph(dx, dy)
  local g = get_glyph(cur_char)
  local ng = {}
  local mask = (1 << cur_font.cw) - 1
  for y = 1, cur_font.ch do
    local sy = y - dy
    if sy >= 1 and sy <= cur_font.ch then
      local row = g[sy]
      if dx > 0 then
        row = (row >> dx) & mask
      elseif dx < 0 then
        row = (row << (-dx)) & mask
      end
      ng[y] = row
    else
      ng[y] = 0
    end
  end
  for y = 1, cur_font.ch do
    g[y] = ng[y]
  end
end

local function copy_glyph()
  local g = get_glyph(cur_char)
  clipboard = {}
  for y = 1, cur_font.ch do
    clipboard[y] = g[y]
  end
  set_notice("Copied glyph 0x" .. string.format("%02X", cur_char))
end

local function paste_glyph()
  if not clipboard then
    set_notice("Clipboard empty")
    return
  end
  local g = get_glyph(cur_char)
  for y = 1, cur_font.ch do
    g[y] = clipboard[y] or 0
  end
  set_notice("Pasted into glyph 0x" .. string.format("%02X", cur_char))
end

local function export_font()
  save({ active_idx = active_font_idx, fonts = fonts })
  local stem = cur_font.stem or (cur_font.name:gsub("%s+", "_"):lower():sub(1, 12))
  local data = pack_bmf(cur_font)
  if font_write then
    local ok, err = font_write(stem, data)
    if ok then
      set_notice("Salvato in /bmf/" .. stem .. ".bmf!")
      return
    end
  end
  set_notice("Salvato nei dati utente (/bm/save)!")
end

local function create_new_font()
  local ncw, nch = 8, 16
  if new_font_size == "8x8" then ncw, nch = 8, 8
  elseif new_font_size == "6x12" then ncw, nch = 6, 12 end
  
  local base_hex = HEX_INTER_8X16
  if new_font_base == "terminus" then base_hex = HEX_ORIG_8X16
  elseif new_font_base == "6x12" then base_hex = HEX_6X12 end
  
  local gl = parse_hex_glyphs(base_hex, nch)
  local stem = "font_" .. (#fonts + 1)
  local nf = {
    name = "Custom " .. (#fonts + 1),
    stem = stem,
    cw = ncw,
    ch = nch,
    glyphs = gl
  }
  table.insert(fonts, nf)
  active_font_idx = #fonts
  cur_font = nf
  if font_write then
    font_write(stem, pack_bmf(nf))
  end
  new_modal_open = false
  set_notice("Creato /bmf/" .. stem .. ".bmf!")
end

-- Layout Constants
local GRID_X = 20
local GRID_Y = 40
local GRID_MAX_W = 128
local GRID_MAX_H = 256

local SHEET_X = 180
local SHEET_Y = 40
local SHEET_COLS = 16
local SHEET_ROWS = 16
local SHEET_CELL_W = 18
local SHEET_CELL_H = 18

-- Right Panel Layout Constants
local RP_X = 484
local RP_W = 148

local TOOL_BOX_Y = 34
local TOOL_BOX_H = 130

local SCALE_Y = 38
local SCALE_BTN_W = 26
local SCALE_BTN_H = 16
local SCALE_1_X = 540
local SCALE_2_X = 570
local SCALE_3_X = 600

local BTN_COL1_X = 490
local BTN_COL2_X = 562
local BTN_W = 66
local BTN_H = 16

local OP_ROW1_Y = 58
local OP_ROW2_Y = 78
local SHIFT_ROW_Y = 98
local CLIP_ROW_Y = 118
local SAVE_ROW_Y = 138
local SAVE_BTN_H = 20

local SHIFT_BTN_W = 30
local SHIFT_BTN_H = 16
local SHIFT_L_X = 490
local SHIFT_U_X = 526
local SHIFT_D_X = 562
local SHIFT_R_X = 598

local PV_BOX_Y = 170
local PV_BOX_H = 166

-- Dropdown Menu Constants
local DROP_X = 14
local DROP_Y = 26
local DROP_W = 200
local DROP_ITEM_H = 20

-- Modal Constants
local MODAL_W = 240
local MODAL_H = 190
local MODAL_X = math.floor((640 - MODAL_W) / 2)
local MODAL_Y = math.floor((360 - MODAL_H) / 2)

local last_mb = 0
local mx, my, mb = -1, -1, 0
local grid_drawing = false
local grid_erasing = false
local sheet_selecting = false

function _init()
  if mouse then mouse(true) end
  init_fonts()
end

function _update()
  if notice_timer > 0 then
    notice_timer = notice_timer - 1
  end

  if mouse then
    local x, y, b = mouse()
    mx = x or -1
    my = y or -1
    mb = b or 0
  else
    mx, my, mb = -1, -1, 0
  end

  local mb1 = (mb & 1) ~= 0
  local mb2 = (mb & 2) ~= 0
  local last_mb1 = (last_mb & 1) ~= 0
  local last_mb2 = (last_mb & 2) ~= 0

  -- mousep(0) is Left Click in BareMetal, mousep(1) is Right Click
  local click = (mousep and (mousep(0) or false)) or (mb1 and not last_mb1)
  local rclick = (mousep and (mousep(1) or false)) or (mb2 and not last_mb2)
  local hold = mb1
  local rhold = mb2
  last_mb = mb

  if not mb1 then
    grid_drawing = false
    sheet_selecting = false
  end
  if not mb2 then
    grid_erasing = false
  end

  -- Modal: New Font Creation
  if new_modal_open then
    if click then
      -- Dimension options
      if mx >= MODAL_X + 20 and mx <= MODAL_X + 80 and my >= MODAL_Y + 52 and my <= MODAL_Y + 72 then
        new_font_size = "8x16"
      elseif mx >= MODAL_X + 90 and mx <= MODAL_X + 150 and my >= MODAL_Y + 52 and my <= MODAL_Y + 72 then
        new_font_size = "8x8"
      elseif mx >= MODAL_X + 160 and mx <= MODAL_X + 220 and my >= MODAL_Y + 52 and my <= MODAL_Y + 72 then
        new_font_size = "6x12"
      -- Template options
      elseif mx >= MODAL_X + 20 and mx <= MODAL_X + 110 and my >= MODAL_Y + 100 and my <= MODAL_Y + 120 then
        new_font_base = "inter"
      elseif mx >= MODAL_X + 120 and mx <= MODAL_X + 210 and my >= MODAL_Y + 100 and my <= MODAL_Y + 120 then
        new_font_base = "terminus"
      -- Action buttons
      elseif mx >= MODAL_X + 20 and mx <= MODAL_X + 110 and my >= MODAL_Y + 145 and my <= MODAL_Y + 171 then
        create_new_font()
      elseif mx >= MODAL_X + 130 and mx <= MODAL_X + 220 and my >= MODAL_Y + 145 and my <= MODAL_Y + 171 then
        new_modal_open = false
      end
    end
    return
  end
  
  -- Handle Dropdown menu (keyboard arrows, enter, and mouse clicks)
  if dropdown_open then
    -- Mouse hover updates selected index
    local action_y = DROP_Y + #fonts * DROP_ITEM_H + 4
    if mx >= DROP_X and mx < DROP_X + DROP_W then
      if my >= DROP_Y and my < DROP_Y + #fonts * DROP_ITEM_H then
        dropdown_sel_idx = math.floor((my - DROP_Y) / DROP_ITEM_H) + 1
      elseif my >= action_y and my < action_y + DROP_ITEM_H then
        dropdown_sel_idx = #fonts + 1
      elseif my >= action_y + DROP_ITEM_H and my < action_y + DROP_ITEM_H * 2 then
        dropdown_sel_idx = #fonts + 2
      end
    end

    -- Keyboard navigation
    local k = keyp()
    while k do
      if k == "up" then
        dropdown_sel_idx = dropdown_sel_idx - 1
        if dropdown_sel_idx < 1 then dropdown_sel_idx = #fonts + 2 end
      elseif k == "down" then
        dropdown_sel_idx = dropdown_sel_idx + 1
        if dropdown_sel_idx > #fonts + 2 then dropdown_sel_idx = 1 end
      elseif k == "\r" or k == "\n" or k == "enter" or k == "return" or k == " " then
        if dropdown_sel_idx <= #fonts then
          select_font(dropdown_sel_idx)
          dropdown_open = false
          set_notice("Selezionato " .. fonts[dropdown_sel_idx].name)
        elseif dropdown_sel_idx == #fonts + 1 then
          dropdown_open = false
          new_modal_open = true
        elseif dropdown_sel_idx == #fonts + 2 then
          dropdown_open = false
          export_font()
        end
        return
      elseif k == "\t" or k == "escape" or k == "esc" or k == "\x1b" or k == "m" or k == "f" then
        dropdown_open = false
        return
      end
      k = keyp()
    end

    -- Mouse click selection
    if click then
      if mx >= DROP_X and mx < DROP_X + DROP_W then
        if dropdown_sel_idx <= #fonts then
          select_font(dropdown_sel_idx)
          dropdown_open = false
          set_notice("Selezionato " .. fonts[dropdown_sel_idx].name)
        elseif dropdown_sel_idx == #fonts + 1 then
          dropdown_open = false
          new_modal_open = true
        elseif dropdown_sel_idx == #fonts + 2 then
          dropdown_open = false
          export_font()
        else
          dropdown_open = false
        end
      else
        dropdown_open = false
      end
    end
    return
  end
  
  -- Top Dropdown button click
  if click and mx >= 14 and mx <= 180 and my >= 4 and my <= 24 then
    dropdown_open = true
    dropdown_sel_idx = active_font_idx
    return
  end
  
  -- Interactive Scale buttons click
  if click and my >= SCALE_Y and my < SCALE_Y + SCALE_BTN_H then
    if mx >= SCALE_1_X and mx < SCALE_1_X + SCALE_BTN_W then preview_scale = 1 end
    if mx >= SCALE_2_X and mx < SCALE_2_X + SCALE_BTN_W then preview_scale = 2 end
    if mx >= SCALE_3_X and mx < SCALE_3_X + SCALE_BTN_W then preview_scale = 3 end
  end

  -- Grid Drawing: only draws if click/drag was initiated inside the grid
  local cell_size = math.min(math.floor(GRID_MAX_W / cur_font.cw), math.floor(GRID_MAX_H / cur_font.ch))
  local grid_w = cur_font.cw * cell_size
  local grid_h = cur_font.ch * cell_size
  local in_grid = mx >= GRID_X and mx < GRID_X + grid_w and my >= GRID_Y and my < GRID_Y + grid_h
  if in_grid then
    if click then grid_drawing = true end
    if rclick then grid_erasing = true end
    local gx = math.floor((mx - GRID_X) / cell_size) + 1
    local gy = math.floor((my - GRID_Y) / cell_size) + 1
    if grid_drawing then
      set_pixel(cur_char, gx, gy, true)
    elseif grid_erasing then
      set_pixel(cur_char, gx, gy, false)
    end
  end

  -- Sheet Selection: only selects if click was initiated inside the sheet
  local in_sheet = mx >= SHEET_X and mx < SHEET_X + SHEET_COLS * SHEET_CELL_W and
                   my >= SHEET_Y and my < SHEET_Y + SHEET_ROWS * SHEET_CELL_H
  if in_sheet then
    if click then sheet_selecting = true end
    if sheet_selecting then
      local col = math.floor((mx - SHEET_X) / SHEET_CELL_W)
      local row = math.floor((my - SHEET_Y) / SHEET_CELL_H)
      cur_char = row * 16 + col
    end
  end

  -- Tool buttons
  if click then
    -- Operations Row 1: Clear, Invert
    if my >= OP_ROW1_Y and my < OP_ROW1_Y + BTN_H then
      if mx >= BTN_COL1_X and mx < BTN_COL1_X + BTN_W then
        clear_glyph()
      elseif mx >= BTN_COL2_X and mx < BTN_COL2_X + BTN_W then
        invert_glyph()
      end
    -- Operations Row 2: FlipH, FlipV
    elseif my >= OP_ROW2_Y and my < OP_ROW2_Y + BTN_H then
      if mx >= BTN_COL1_X and mx < BTN_COL1_X + BTN_W then
        flip_h()
      elseif mx >= BTN_COL2_X and mx < BTN_COL2_X + BTN_W then
        flip_v()
      end
    -- Shift Row: [<] [^] [v] [>]
    elseif my >= SHIFT_ROW_Y and my < SHIFT_ROW_Y + SHIFT_BTN_H then
      if mx >= SHIFT_L_X and mx < SHIFT_L_X + SHIFT_BTN_W then
        shift_glyph(-1, 0)
      elseif mx >= SHIFT_U_X and mx < SHIFT_U_X + SHIFT_BTN_W then
        shift_glyph(0, -1)
      elseif mx >= SHIFT_D_X and mx < SHIFT_D_X + SHIFT_BTN_W then
        shift_glyph(0, 1)
      elseif mx >= SHIFT_R_X and mx < SHIFT_R_X + SHIFT_BTN_W then
        shift_glyph(1, 0)
      end
    -- Clipboard Row: Copia, Incolla
    elseif my >= CLIP_ROW_Y and my < CLIP_ROW_Y + BTN_H then
      if mx >= BTN_COL1_X and mx < BTN_COL1_X + BTN_W then
        copy_glyph()
      elseif mx >= BTN_COL2_X and mx < BTN_COL2_X + BTN_W then
        paste_glyph()
      end
    -- Save Button
    elseif my >= SAVE_ROW_Y and my < SAVE_ROW_Y + SAVE_BTN_H then
      if mx >= BTN_COL1_X and mx < BTN_COL1_X + 138 then
        export_font()
      end
    end
  end

  -- Typed keys
  local k = keyp()
  while k do
    if k == "\t" or k == "m" or k == "f" then
      dropdown_open = not dropdown_open
      if dropdown_open then dropdown_sel_idx = active_font_idx end
    elseif k == "^s" or k == "ctrl s" then
      export_font()
    elseif k == "^c" or k == "ctrl c" then
      copy_glyph()
    elseif k == "^v" or k == "ctrl v" then
      paste_glyph()
    elseif k == "1" then
      preview_scale = 1
    elseif k == "2" then
      preview_scale = 2
    elseif k == "3" then
      preview_scale = 3
    elseif k == "left" then
      cur_char = (cur_char - 1) & 0xFF
    elseif k == "right" then
      cur_char = (cur_char + 1) & 0xFF
    elseif k == "up" then
      cur_char = (cur_char - 16) & 0xFF
    elseif k == "down" then
      cur_char = (cur_char + 16) & 0xFF
    end
    k = keyp()
  end
end

local function draw_glyph_scaled(c, dx, dy, scale, col)
  local g = get_glyph(c)
  for y = 1, cur_font.ch do
    local r = g[y] or 0
    for x = 1, cur_font.cw do
      if (r & (1 << (cur_font.cw - x))) ~= 0 then
        if scale == 1 then
          pset(dx + x - 1, dy + y - 1, col)
        else
          rectfill(dx + (x - 1) * scale, dy + (y - 1) * scale, scale, scale, col)
        end
      end
    end
  end
end

function _draw()
  cls(C.bg)

  -- Header
  rectfill(0, 0, 640, 28, C.panel)
  line(0, 28, 639, 28, C.border)
  
  -- Dropdown Menu Button
  rectfill(14, 4, 166, 20, dropdown_open and C.btn_hi or C.btn)
  rect(14, 4, 166, 20, dropdown_open and C.cyan or C.border)
  print("Font: " .. cur_font.name .. "  v", 20, 6, dropdown_open and C.cyan or C.btn_text)
  
  -- Glyph info
  local char_rep = (cur_char >= 32 and cur_char <= 126) and string.char(cur_char) or "?"
  local info_str = string.format("Glyph: '%s'  Dec: %d  Hex: 0x%02X", char_rep, cur_char, cur_char)
  print(info_str, 200, 6, C.white)

  -- Notice badge
  if notice_timer > 0 then
    print(notice, 440, 6, C.cyan)
  end

  -- Left Panel: Large Glyph Editor
  local cell_size = math.min(math.floor(GRID_MAX_W / cur_font.cw), math.floor(GRID_MAX_H / cur_font.ch))
  local grid_w = cur_font.cw * cell_size
  local grid_h = cur_font.ch * cell_size

  rectfill(GRID_X - 6, GRID_Y - 6, grid_w + 12, grid_h + 12, C.panel)
  rect(GRID_X - 6, GRID_Y - 6, grid_w + 12, grid_h + 12, C.border)

  for y = 1, cur_font.ch do
    for x = 1, cur_font.cw do
      local on = get_pixel(cur_char, x, y)
      local px = GRID_X + (x - 1) * cell_size
      local py = GRID_Y + (y - 1) * cell_size
      rectfill(px, py, cell_size - 1, cell_size - 1, on and C.pixel_on or C.pixel_off)
    end
  end

  -- Baseline guide
  line(GRID_X, GRID_Y + grid_h, GRID_X + grid_w, GRID_Y + grid_h, C.accent)

  -- Center Panel: Code Page 437 Sheet
  rectfill(SHEET_X - 6, SHEET_Y - 6, SHEET_COLS * SHEET_CELL_W + 12, SHEET_ROWS * SHEET_CELL_H + 12, C.panel)
  rect(SHEET_X - 6, SHEET_Y - 6, SHEET_COLS * SHEET_CELL_W + 12, SHEET_ROWS * SHEET_CELL_H + 12, C.border)

  for r = 0, SHEET_ROWS - 1 do
    for col = 0, SHEET_COLS - 1 do
      local ch_idx = r * 16 + col
      local cx = SHEET_X + col * SHEET_CELL_W
      local cy = SHEET_Y + r * SHEET_CELL_H

      if ch_idx == cur_char then
        rect(cx - 1, cy - 1, SHEET_CELL_W + 1, SHEET_CELL_H + 1, C.yellow)
      end

      local gx = cx + math.floor((SHEET_CELL_W - cur_font.cw) / 2)
      local gy = cy + math.floor((SHEET_CELL_H - cur_font.ch) / 2)
      draw_glyph_scaled(ch_idx, gx, gy, 1, (ch_idx == cur_char) and C.yellow or C.text)
    end
  end

  -- Right Panel: Tools and Previews
  rectfill(RP_X - 4, TOOL_BOX_Y, RP_W + 8, TOOL_BOX_H, C.panel)
  rect(RP_X - 4, TOOL_BOX_Y, RP_W + 8, TOOL_BOX_H, C.border)

  -- Row 1: Scale selectors
  print("Scala:", RP_X + 6, SCALE_Y + 4, C.dim)
  local scales = { { 1, SCALE_1_X }, { 2, SCALE_2_X }, { 3, SCALE_3_X } }
  for _, sc in ipairs(scales) do
    local s = sc[1]
    local bx = sc[2]
    local is_active = (preview_scale == s)
    rectfill(bx, SCALE_Y, SCALE_BTN_W, SCALE_BTN_H, is_active and C.cyan or C.btn)
    rect(bx, SCALE_Y, SCALE_BTN_W, SCALE_BTN_H, is_active and C.white or C.border)
    print(s .. "x", bx + 5, SCALE_Y + 4, is_active and C.black or C.btn_text)
  end

  -- Row 2: Clear, Invert
  rectfill(BTN_COL1_X, OP_ROW1_Y, BTN_W, BTN_H, C.btn)
  rect(BTN_COL1_X, OP_ROW1_Y, BTN_W, BTN_H, C.border)
  print("Clear", BTN_COL1_X + 13, OP_ROW1_Y + 4, C.btn_text)

  rectfill(BTN_COL2_X, OP_ROW1_Y, BTN_W, BTN_H, C.btn)
  rect(BTN_COL2_X, OP_ROW1_Y, BTN_W, BTN_H, C.border)
  print("Invert", BTN_COL2_X + 9, OP_ROW1_Y + 4, C.btn_text)

  -- Row 3: FlipH, FlipV
  rectfill(BTN_COL1_X, OP_ROW2_Y, BTN_W, BTN_H, C.btn)
  rect(BTN_COL1_X, OP_ROW2_Y, BTN_W, BTN_H, C.border)
  print("FlipH", BTN_COL1_X + 13, OP_ROW2_Y + 4, C.btn_text)

  rectfill(BTN_COL2_X, OP_ROW2_Y, BTN_W, BTN_H, C.btn)
  rect(BTN_COL2_X, OP_ROW2_Y, BTN_W, BTN_H, C.border)
  print("FlipV", BTN_COL2_X + 13, OP_ROW2_Y + 4, C.btn_text)

  -- Row 4: Shift [<] [^] [v] [>]
  local shifts = {
    { "<", SHIFT_L_X },
    { "^", SHIFT_U_X },
    { "v", SHIFT_D_X },
    { ">", SHIFT_R_X },
  }
  for _, sh in ipairs(shifts) do
    rectfill(sh[2], SHIFT_ROW_Y, SHIFT_BTN_W, SHIFT_BTN_H, C.btn)
    rect(sh[2], SHIFT_ROW_Y, SHIFT_BTN_W, SHIFT_BTN_H, C.border)
    print(sh[1], sh[2] + 11, SHIFT_ROW_Y + 4, C.btn_text)
  end

  -- Row 5: Copia, Incolla
  rectfill(BTN_COL1_X, CLIP_ROW_Y, BTN_W, BTN_H, C.btn)
  rect(BTN_COL1_X, CLIP_ROW_Y, BTN_W, BTN_H, C.border)
  print("Copia", BTN_COL1_X + 13, CLIP_ROW_Y + 4, C.btn_text)

  rectfill(BTN_COL2_X, CLIP_ROW_Y, BTN_W, BTN_H, C.btn)
  rect(BTN_COL2_X, CLIP_ROW_Y, BTN_W, BTN_H, C.border)
  print("Incolla", BTN_COL2_X + 5, CLIP_ROW_Y + 4, C.btn_text)

  -- Row 6: Salva in /bmf
  rectfill(BTN_COL1_X, SAVE_ROW_Y, 138, SAVE_BTN_H, C.btn_hi)
  rect(BTN_COL1_X, SAVE_ROW_Y, 138, SAVE_BTN_H, C.green)
  print("Salva in /bmf", BTN_COL1_X + 13, SAVE_ROW_Y + 6, C.green)

  -- Live Preview box
  rectfill(RP_X - 4, PV_BOX_Y, RP_W + 8, PV_BOX_H, C.panel)
  rect(RP_X - 4, PV_BOX_Y, RP_W + 8, PV_BOX_H, C.border)
  print("Live Preview (" .. preview_scale .. "x):", RP_X + 6, PV_BOX_Y + 6, C.dim)

  local preview_lines
  if preview_scale == 1 then
    preview_lines = {
      "BareMetal 2026",
      "Quick brown fox",
      "jumps over dog",
      "0123456789",
      "AaBbCcDdEeFf",
      "!@#$%^&*()-+",
    }
  elseif preview_scale == 2 then
    preview_lines = {
      "BareMetal",
      "BMF Font",
      "01234567",
      "AaBbCc",
    }
  else
    preview_lines = {
      "Bare",
      "BMF!",
      "123",
    }
  end

  local line_spacing = (cur_font.ch + 2) * preview_scale
  local py = PV_BOX_Y + 22
  for _, line_txt in ipairs(preview_lines) do
    if py + cur_font.ch * preview_scale > PV_BOX_Y + PV_BOX_H - 4 then break end
    local px = RP_X + 6
    for i = 1, #line_txt do
      local ch_code = line_txt:byte(i)
      draw_glyph_scaled(ch_code, px, py, preview_scale, C.white)
      px = px + cur_font.cw * preview_scale
      if px + cur_font.cw * preview_scale > RP_X + RP_W then break end
    end
    py = py + line_spacing
  end

  -- Dropdown Menu Overlay
  if dropdown_open then
    local dh = #fonts * DROP_ITEM_H + 50
    rectfill(DROP_X, DROP_Y, DROP_W, dh, C.panel_hi)
    rect(DROP_X, DROP_Y, DROP_W, dh, C.cyan)
    for idx, f in ipairs(fonts) do
      local iy = DROP_Y + (idx - 1) * DROP_ITEM_H
      local is_sel = (idx == dropdown_sel_idx)
      local is_active = (idx == active_font_idx)
      if is_sel then
        rectfill(DROP_X + 2, iy + 1, DROP_W - 4, DROP_ITEM_H - 2, C.btn_hi)
        rect(DROP_X + 2, iy + 1, DROP_W - 4, DROP_ITEM_H - 2, C.cyan)
      elseif is_active then
        rectfill(DROP_X + 2, iy + 1, DROP_W - 4, DROP_ITEM_H - 2, C.panel)
      end
      local prefix = is_active and "> " or "  "
      local col = is_sel and C.cyan or (is_active and C.white or C.text)
      print(prefix .. f.name .. " (" .. f.cw .. "x" .. f.ch .. ")", DROP_X + 6, iy + 4, col)
    end
    -- Dropdown action buttons
    local action_y = DROP_Y + #fonts * DROP_ITEM_H + 4
    line(DROP_X, action_y, DROP_X + DROP_W, action_y, C.border)

    local is_sel_nuovo = (dropdown_sel_idx == #fonts + 1)
    if is_sel_nuovo then
      rectfill(DROP_X + 2, action_y + 1, DROP_W - 4, DROP_ITEM_H - 2, C.btn_hi)
      rect(DROP_X + 2, action_y + 1, DROP_W - 4, DROP_ITEM_H - 2, C.yellow)
    end
    print("+ Nuovo Font...", DROP_X + 10, action_y + 4, is_sel_nuovo and C.white or C.yellow)

    local is_sel_salva = (dropdown_sel_idx == #fonts + 2)
    if is_sel_salva then
      rectfill(DROP_X + 2, action_y + DROP_ITEM_H + 1, DROP_W - 4, DROP_ITEM_H - 2, C.btn_hi)
      rect(DROP_X + 2, action_y + DROP_ITEM_H + 1, DROP_W - 4, DROP_ITEM_H - 2, C.green)
    end
    print("v Salva in /bmf", DROP_X + 10, action_y + DROP_ITEM_H + 4, is_sel_salva and C.white or C.green)
  end

  -- Modal Window: New Font
  if new_modal_open then
    rectfill(0, 0, 640, 360, 0x88000000) -- backdrop
    rectfill(MODAL_X, MODAL_Y, MODAL_W, MODAL_H, C.panel)
    rect(MODAL_X, MODAL_Y, MODAL_W, MODAL_H, C.cyan)
    print("Crea Nuovo Font", MODAL_X + 60, MODAL_Y + 12, C.white)

    print("Dimensioni glifo:", MODAL_X + 20, MODAL_Y + 36, C.dim)
    local sizes = { { "8x16", 20 }, { "8x8", 90 }, { "6x12", 160 } }
    for _, s in ipairs(sizes) do
      local bx = MODAL_X + s[2]
      rectfill(bx, MODAL_Y + 52, 60, 20, (new_font_size == s[1]) and C.cyan or C.btn)
      rect(bx, MODAL_Y + 52, 60, 20, C.border)
      print(s[1], bx + 14, MODAL_Y + 56, (new_font_size == s[1]) and C.black or C.btn_text)
    end

    print("Template base:", MODAL_X + 20, MODAL_Y + 84, C.dim)
    local templates = { { "Inter", "inter", 20 }, { "Terminus", "terminus", 120 } }
    for _, t in ipairs(templates) do
      local bx = MODAL_X + t[3]
      rectfill(bx, MODAL_Y + 100, 90, 20, (new_font_base == t[2]) and C.cyan or C.btn)
      rect(bx, MODAL_Y + 100, 90, 20, C.border)
      print(t[1], bx + 16, MODAL_Y + 104, (new_font_base == t[2]) and C.black or C.btn_text)
    end

    -- Confirm / Cancel
    rectfill(MODAL_X + 20, MODAL_Y + 145, 90, 26, C.green)
    print("Crea", MODAL_X + 50, MODAL_Y + 152, C.black)

    rectfill(MODAL_X + 130, MODAL_Y + 145, 90, 26, C.btn_hi)
    rect(MODAL_X + 130, MODAL_Y + 145, 90, 26, C.border)
    print("Annulla", MODAL_X + 150, MODAL_Y + 152, C.btn_text)
  end

  -- Bottom key hints
  rectfill(0, 342, 640, 18, C.panel)
  line(0, 342, 639, 342, C.border)
  if dropdown_open then
    print("[Freccia Su/Giu] Scegli   [Invio] Conferma   [Esc/Tab] Chiudi", 14, 346, C.cyan)
  else
    print("[Mouse] Edita   [Tab] Menu Font   [1/2/3] Zoom   [Ctrl+S] Salva in /bmf", 14, 346, C.dim)
  end
end
